def variants(q,a,cat,i):
    prefixes=['','Калі ласка, ','Патлумач: ','Адкажы коратка: ','Мне цікава: ']
    suffixes=['',' Дай кароткі адказ.',' Адкажы па-беларуску.']
    p=prefixes[i%len(prefixes)]; s=suffixes[(i//len(prefixes))%len(suffixes)]
    qq=(p+q+s).strip()
    aa=a
    if i%7==0 and cat not in {'safety','unknown_refusal'}:
        aa += ' Калі патрэбна, магу працягнуць больш падрабязна.'
    return qq,aa

def record(q,a,cat,split,idx):
    return {'messages':[{'role':'user','content':q},{'role':'assistant','content':a}], 'category':cat, 'split':split, 'source':'gpt_pro_curated_hotfix6_seed', 'synthetic':True, 'license':'project-authored', 'id':hashlib.sha1(f'{cat}:{split}:{idx}:{q}'.encode()).hexdigest()[:16]}

def build(n_per_cat_train=120,n_per_cat_val=20,n_per_cat_eval=30):
    train=[]; val=[]; ev=[]
    for cat,base in CATS.items():
        for i in range(n_per_cat_train+n_per_cat_val+n_per_cat_eval):
            q,a=base[i%len(base)]
            q,a=variants(q,a,cat,i)
            if i<n_per_cat_train: train.append(record(q,a,cat,'train',i))
            elif i<n_per_cat_train+n_per_cat_val: val.append(record(q,a,cat,'val',i))
            else: ev.append(record(q,a,cat,'eval',i))
    random.shuffle(train); random.shuffle(val); random.shuffle(ev)
    return train,val,ev

def write_jsonl(path,rows):
    path.parent.mkdir(parents=True,exist_ok=True)
    with path.open('w',encoding='utf-8') as f:
        for r in rows: f.write(json.dumps(r,ensure_ascii=False)+'\n')

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--pack-dir',default='.')
    args=ap.parse_args(); pack=Path(args.pack_dir)
    tr,val,ev=build()
    write_jsonl(pack/'seed_sft/sft_v6_governed_balanced_train.be.jsonl',tr)
    write_jsonl(pack/'seed_sft/sft_v6_governed_balanced_val.be.jsonl',val)
    write_jsonl(pack/'eval/sft_v6_governed_balanced_eval.be.jsonl',ev)
    report={'train':len(tr),'val':len(val),'eval':len(ev),'categories':Counter(r['category'] for r in tr),'max_category_share':max(Counter(r['category'] for r in tr).values())/len(tr)}
    (pack/'reports').mkdir(exist_ok=True)
    (pack/'reports/sft_v6_governed_seed_report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps(report,ensure_ascii=False,indent=2))
if __name__=='__main__': main()
